var app = new Vue({
  el: "#app",
  delimiters: ["[[", "]]"],
  data: {
    errors: ["", ""],
    newTagText: [],
    l_tag: [],
    l_tags: [],
    u_tag: [],
    u_tags: [],
  },
  methods: {
    loadTags() {
      const path =
        window.location.origin + "/dashboard/keywords/list";
      axios
        .get(path)
        .then((response) => {
          this.l_tags = response.data.l_dict;
          this.u_tags = response.data.u_dict;
        })
        .catch((error) => {
          console.log(error);
        });
    },
    updateTags(newTags, specific, key) {
      if (specific === 0) {
        this.l_tags[key].value = newTags;
      } else {
        this.u_tags[key].value = newTags;
      }
      this.uploadTags();
    },
    uploadTags() {
      const path = window.location.origin + "/dashboard/keywords";
      axios
        .post(path, {
          l_dict: this.l_tags,
          u_dict: this.u_tags,
        })
        .catch((error) => {
          console.log(error);
        });
    },
    addNewListTag(specific) {
      if (!this.newTagText[specific]) {
        Vue.set(this.errors, specific, "Không được để trống!");
      } else {
        if (specific === 0) {
          this.l_tags.push({
            name: this.newTagText[specific],
            value: [],
          });
        } else {
          this.u_tags.push({
            name: this.newTagText[specific],
            value: [],
          });
        }
        this.errors = ["", ""];
        this.newTagText = [];
      }
    },
    deleteListTag(specific, key) {
      if (specific === 0) {
        this.l_tags.splice(key, 1);
      } else {
        this.u_tags.splice(key, 1);
      }
      this.uploadTags();
    },
  },
  created() {
    this.loadTags();
  },
});
